    public void pruneTriggerBlocks(double distance) {
        for (int l = this.blockTriggers.size() - 1; l >= 0; --l) {
            BlockCollisionData blockCollisionData = this.blockTriggers.get(l);
            if (blockCollisionData.collisionStart <= distance) break;
            this.blockTriggers.remove(l);
        }
    }

    @Nonnull
    public CollisionDataArray<BlockCollisionData> getTriggerBlocks() {
        return this.blockTriggers;
    }

    public int defaultTriggerBlocksProcessing(@Nonnull InteractionManager manager, @Nonnull Entity entity, @Nonnull Ref<EntityStore> ref, boolean executeTriggers, @Nonnull ComponentAccessor<EntityStore> componentAccessor) {
        World world = componentAccessor.getExternalData().getWorld();
        LongSet temp = this.lastTriggers;
        this.lastTriggers = this.newTriggers;
        this.newTriggers = temp;
        this.newTriggers.clear();
        int damageToEntity = 0;
        CollisionDataArray<BlockCollisionData> triggerBlocks = this.getTriggerBlocks();
        int size = triggerBlocks.size();
        for (int i = 0; i < size; ++i) {
            long index;
            String interactions;
            WorldChunk chunk;
            int damageToEntities;
            BlockCollisionData triggerCollision = triggerBlocks.get(i);
            if (triggerCollision.blockType != null && (damageToEntities = Math.max(triggerCollision.blockType.getDamageToEntities(), triggerCollision.fluid.getDamageToEntities())) > damageToEntity) {
                damageToEntity = damageToEntities;
            }
            if (!executeTriggers || !(entity instanceof LivingEntity) || (chunk = world.getChunkIfInMemory(ChunkUtil.indexChunkFromBlock(triggerCollision.x, triggerCollision.z))) == null) continue;
            BlockType blockType = chunk.getBlockType(triggerCollision.x, triggerCollision.y, triggerCollision.z);
            Fluid fluidType = Fluid.getAssetMap().getAsset(chunk.getFluidId(triggerCollision.x, triggerCollision.y, triggerCollision.z));
            String interactionsEnter = blockType.getInteractions().get((Object)InteractionType.CollisionEnter);
            if (interactionsEnter == null) {
                interactionsEnter = fluidType.getInteractions().get((Object)InteractionType.CollisionEnter);
            }
            if ((interactions = blockType.getInteractions().get((Object)InteractionType.Collision)) == null) {
                interactions = fluidType.getInteractions().get((Object)InteractionType.Collision);
            }
            if (interactionsEnter == null && interactions == null) continue;
            int filler = chunk.getFiller(triggerCollision.x, triggerCollision.y, triggerCollision.z);
            int x = triggerCollision.x;
            int y = triggerCollision.y;
            int z = triggerCollision.z;
            if (filler != 0) {
                x -= FillerBlockUtil.unpackX(filler);
                y -= FillerBlockUtil.unpackY(filler);
                z -= FillerBlockUtil.unpackZ(filler);
            }
            if (!this.newTriggers.add(index = BlockUtil.packUnchecked(x, y, z))) continue;
            BlockPosition pos = new BlockPosition(x, y, z);
            if (!this.lastTriggers.remove(index) && interactionsEnter != null) {
                this.doCollisionInteraction(manager, InteractionType.CollisionEnter, ref, interactionsEnter, pos, componentAccessor);
            }
            if (interactions == null) continue;
            this.doCollisionInteraction(manager, InteractionType.Collision, ref, interactions, pos, componentAccessor);
        }
        if (executeTriggers && entity instanceof LivingEntity && !this.lastTriggers.isEmpty()) {
            for (Long old : this.lastTriggers) {
                int x = BlockUtil.unpackX(old);
                int y = BlockUtil.unpackY(old);
                int z = BlockUtil.unpackZ(old);
                WorldChunk chunk = world.getChunkIfInMemory(ChunkUtil.indexChunkFromBlock(x, z));
                if (chunk == null) continue;
                BlockType blockType = chunk.getBlockType(x, y, z);
                Fluid fluidType = Fluid.getAssetMap().getAsset(chunk.getFluidId(x, y, z));
                String interactions = blockType.getInteractions().get((Object)InteractionType.CollisionLeave);
                if (interactions == null) {
                    interactions = fluidType.getInteractions().get((Object)InteractionType.CollisionLeave);
                }
                if (interactions == null) continue;
                this.doCollisionInteraction(manager, InteractionType.CollisionLeave, ref, interactions, new BlockPosition(x, y, z), componentAccessor);
            }
        }
        return damageToEntity;
    }

    private void doCollisionInteraction(@Nonnull InteractionManager manager, @Nonnull InteractionType type, @Nonnull Ref<EntityStore> ref, @Nonnull String interactions, @Nonnull BlockPosition pos, @Nonnull ComponentAccessor<EntityStore> componentAccessor) {
        RootInteraction root = RootInteraction.getRootInteractionOrUnknown(interactions);
        World world = componentAccessor.getExternalData().getWorld();
        InteractionContext context = InteractionContext.forInteraction(manager, ref, type, componentAccessor);
        context.getMetaStore().putMetaObject(Interaction.TARGET_BLOCK_RAW, pos);
        context.getMetaStore().putMetaObject(Interaction.TARGET_BLOCK, world.getBaseBlock(pos));
        InteractionChain chain = manager.initChain(type, context, root, -1, pos, false);
        manager.queueExecuteChain(chain);
    }

    @Override
    public boolean next() {
        return this.continueAfterCollision || this.haveNoCollision;
    }

    @Override
    public boolean accept(long x, long y, long z) {
        if (this.collisionConfig.canCollide((int)x, (int)y, (int)z)) {
            int numDetails = this.collisionConfig.getDetailCount();
            boolean haveCollision = this.movingBoxBoxCollision.isBoundingBoxColliding(this.collisionConfig.getBoundingBox(), x += (long)this.collisionConfig.getBoundingBoxOffsetX(), y += (long)this.collisionConfig.getBoundingBoxOffsetY(), z += (long)this.collisionConfig.getBoundingBoxOffsetZ());
            if (this.logger != null) {
                String arg7 = this.collisionConfig.blockType != null ? this.collisionConfig.blockType.getId() : "null";
                this.logger.at(Level.INFO).log("?? Block Test at %s/%s/%s numDet=%d haveColl=%s overlap=%s blockType=%s", x, y, z, numDetails, haveCollision, this.movingBoxBoxCollision.isOverlapping(), arg7);
            }
            if (numDetails <= 1) {
                this.processCollisionResult(haveCollision, 0);
            } else if (haveCollision || this.movingBoxBoxCollision.isOverlapping() || this.movingBoxBoxCollision.isTouching()) {
                for (int i = 0; i < numDetails; ++i) {
                    haveCollision = this.movingBoxBoxCollision.isBoundingBoxColliding(this.collisionConfig.getBoundingBox(i), x, y, z);
                    this.processCollisionResult(haveCollision, i);
                }
            }
        } else if (this.recordPassThrough && this.collisionConfig.blockFilteredOut) {
            int numDetails = this.collisionConfig.getDetailCount();
            boolean haveCollision = this.movingBoxBoxCollision.isBoundingBoxColliding(this.collisionConfig.getBoundingBox(), x += (long)this.collisionConfig.getBoundingBoxOffsetX(), y += (long)this.collisionConfig.getBoundingBoxOffsetY(), z += (long)this.collisionConfig.getBoundingBoxOffsetZ());
            if (numDetails <= 1) {
                if (haveCollision) {
                    this.addPassThrough(this.movingBoxBoxCollision, 0);
                }
            } else if (haveCollision || this.movingBoxBoxCollision.isOverlapping() || this.movingBoxBoxCollision.isTouching()) {
                for (int i = 0; i < numDetails; ++i) {
                    haveCollision = this.movingBoxBoxCollision.isBoundingBoxColliding(this.collisionConfig.getBoundingBox(i), x, y, z);
                    if (!haveCollision) continue;
                    this.addPassThrough(this.movingBoxBoxCollision, i);
                }
            }
        } else if (this.logger != null) {
            String arg4 = this.collisionConfig.blockType != null ? this.collisionConfig.blockType.getId() : "null";
            this.logger.at(Level.INFO).log("-- Ignoring block at %s/%s/%s blockType=%s", x, y, z, arg4);
        }
        return true;
    }

    private void processCollisionResult(boolean haveCollision, int hitboxIndex) {
        if (this.logger != null) {
            this.logger.at(Level.INFO).log("?? Further testing block haveCol=%s hitBoxIndex=%s onGround=%s touching=%s canCollide=%s canTrigger=%s", haveCollision, hitboxIndex, this.movingBoxBoxCollision.isOnGround(), this.movingBoxBoxCollision.isTouching(), this.collisionConfig.blockCanCollide, this.collisionConfig.blockCanTrigger);
        }
        if (this.collisionConfig.blockCanCollide) {
            boolean isNoSlideCollision = true;
            if (this.movingBoxBoxCollision.onGround) {
                boolean bl = haveCollision = this.collisionConfig.blockType == null || this.isNonWalkable.test(this.collisionConfig);
                if (!haveCollision) {
                    this.addSlide(this.movingBoxBoxCollision, hitboxIndex);
                    if (this.collisionConfig.blockCanTrigger) {
                        this.addTrigger(this.movingBoxBoxCollision, hitboxIndex);
                    }
                    if (this.logger != null) {
                        this.logger.at(Level.INFO).log("++ Sliding block start=%s end=%s normal=%s", this.movingBoxBoxCollision.getCollisionStart(), this.movingBoxBoxCollision.getCollisionEnd(), Vector3dUtil.formatShortString(this.movingBoxBoxCollision.getCollisionNormal()));
                    }
                    return;
                }
                isNoSlideCollision = false;
                if (this.logger != null) {
                    this.logger.at(Level.INFO).log("?? Sliding block is unwalkable start=%s end=%s normal=%s", this.movingBoxBoxCollision.getCollisionStart(), this.movingBoxBoxCollision.getCollisionEnd(), Vector3dUtil.formatShortString(this.movingBoxBoxCollision.getCollisionNormal()));
                }
            }
            if (haveCollision) {
                this.addCollision(this.movingBoxBoxCollision, hitboxIndex);
                if (isNoSlideCollision) {
                    this.haveNoCollision = false;
                }
                if (this.logger != null) {
                    this.logger.at(Level.INFO).log("++ Collision with block start=%s end=%s normal=%s", this.movingBoxBoxCollision.collisionStart, this.movingBoxBoxCollision.collisionEnd, Vector3dUtil.formatShortString(this.movingBoxBoxCollision.collisionNormal));
                }
            }
        }
        if (this.collisionConfig.blockCanTrigger && (haveCollision || this.movingBoxBoxCollision.isTouching())) {
            if (this.logger != null) {
                this.logger.at(Level.INFO).log("++ Trigger block start=%s end=%s normal=%s", this.movingBoxBoxCollision.getCollisionStart(), this.movingBoxBoxCollision.getCollisionEnd(), Vector3dUtil.formatShortString(this.movingBoxBoxCollision.getCollisionNormal()));
            }
            this.addTrigger(this.movingBoxBoxCollision, hitboxIndex);
        }
    }

    public void iterateBlocks(@Nonnull Box collider, @Nonnull Vector3d pos, @Nonnull Vector3d direction, double length, boolean stopOnCollisionFound, double extent) {
        this.continueAfterCollision = !stopOnCollisionFound;
        Vector3d min = collider.getMin();
        Vector3d max = collider.getMax();
        BoxBlockIterator.iterate(min.x - extent, min.y - extent, min.z - extent, max.x + extent, max.y + extent, max.z + extent, pos.x, pos.y, pos.z, direction.x, direction.y, direction.z, length, this);
    }

