    @Override
    public boolean walk(@Nonnull Collector collector, @Nonnull InteractionContext context) {
        if (this.hitEntity != null && InteractionManager.walkInteractions(collector, context, TAG_HIT_ENTITY, RootInteraction.getRootInteractionOrUnknown(this.hitEntity).getInteractionIds())) {
            return true;
        }
        if (this.hitEntityRules != null) {
            for (int i = 0; i < this.hitEntityRules.length; ++i) {
                HitEntity rule = this.hitEntityRules[i];
                if (rule.next == null || !InteractionManager.walkInteractions(collector, context, HitEntityRuleTag.of(i), RootInteraction.getRootInteractionOrUnknown(rule.next).getInteractionIds())) continue;
                return true;
            }
        }
        if (this.hitBlock != null && InteractionManager.walkInteractions(collector, context, TAG_HIT_BLOCK, RootInteraction.getRootInteractionOrUnknown(this.hitBlock).getInteractionIds())) {
            return true;
        }
        return super.walk(collector, context);
    }

    @Override
    @Nullable
    public InteractionChain mapForkChain(@Nonnull InteractionContext context, @Nonnull InteractionChainData data) {
        if (data.blockPosition != null) {
            return null;
        }
        Long2ObjectMap<InteractionChain> chains = context.getChain().getForkedChains();
        for (InteractionChain chain : chains.values()) {
            if (chain.getBaseForkedChainId().entryIndex != context.getEntry().getIndex()) continue;
            InteractionChainData otherData = chain.getChainData();
            if (otherData.entityId != data.entityId) continue;
            return chain;
        }
        return null;
    }

