import com.hypixel.hytale.server.core.inventory.ItemStack;
import com.hypixel.hytale.server.core.modules.entity.component.ModelComponent;
import com.hypixel.hytale.server.core.modules.entity.component.TransformComponent;
import com.hypixel.hytale.server.core.modules.entity.player.PlayerSettings;
import com.hypixel.hytale.server.core.modules.interaction.interaction.config.InteractionConfiguration;
import com.hypixel.hytale.server.core.universe.world.storage.EntityStore;
import javax.annotation.Nonnull;
import javax.annotation.Nullable;
import org.joml.Vector3d;
import org.joml.Vector3i;

public class InteractionValidation {
    private static final float MAX_INTERACTION_DISTANCE_BUFFER = 2.0f;
    private static final float EXTENDED_CREATIVE_BLOCK_INTERACTION_DISTANCE = 10.0f;
    private static final float MIN_CREATIVE_BLOCK_INTERACTION_DISTANCE = 0.0f;
    private static final float MAX_CREATIVE_BLOCK_INTERACTION_DISTANCE = 128.0f;

    private static float getPlayerInteractionDistanceSq(@Nonnull Ref<EntityStore> ref, @Nonnull ComponentAccessor<EntityStore> componentAccessor, @Nullable ItemStack heldItem) {
        Player playerComponent = componentAccessor.getComponent(ref, Player.getComponentType());
        GameMode gameMode = playerComponent.getGameMode();
        InteractionConfiguration interactionConfig = heldItem != null ? heldItem.getItem().getInteractionConfig() : InteractionConfiguration.DEFAULT;
        float maxDistance = interactionConfig.getUseDistance(gameMode);
        if (gameMode == GameMode.Creative) {
            float creativeDistance = 10.0f;
            PlayerSettings settingsComponent = componentAccessor.getComponent(ref, PlayerSettings.getComponentType());
            if (settingsComponent != null) {
                int clientCreativeDistance = settingsComponent.creativeSettings().creativeInteractionDistance();
                creativeDistance = MathUtil.clamp((float)clientCreativeDistance, 0.0f, 128.0f);
            }
            maxDistance = Math.max(maxDistance, creativeDistance);
        }
        return (maxDistance += 2.0f) * maxDistance;
    }

    private static float getEyeHeight(@Nonnull Ref<EntityStore> ref, @Nonnull ComponentAccessor<EntityStore> componentAccessor) {
        ModelComponent modelComponent = componentAccessor.getComponent(ref, ModelComponent.getComponentType());
        if (modelComponent == null) {
            return 0.0f;
        }
        return modelComponent.getModel().getEyeHeight(ref, componentAccessor);
    }

    public static boolean canPlayerInteractWithEntity(@Nonnull Ref<EntityStore> ref, @Nonnull ComponentAccessor<EntityStore> componentAccessor, @Nullable ItemStack heldItem, @Nonnull Ref<EntityStore> targetRef) {
        Player playerComponent = componentAccessor.getComponent(ref, Player.getComponentType());
        if (playerComponent == null) {
            return true;
        }
        TransformComponent transformComponent = componentAccessor.getComponent(ref, TransformComponent.getComponentType());
        if (transformComponent == null) {
            return false;
        }
        TransformComponent targetTransformComponent = componentAccessor.getComponent(targetRef, TransformComponent.getComponentType());
        if (targetTransformComponent == null) {
            return false;
        }
        float maxDistanceSq = InteractionValidation.getPlayerInteractionDistanceSq(ref, componentAccessor, heldItem);
        float eyeHeight = InteractionValidation.getEyeHeight(ref, componentAccessor);
        Vector3d position = transformComponent.getPosition();
        Vector3d targetPosition = targetTransformComponent.getPosition();
        double distanceSq = targetPosition.distanceSquared(position.x(), position.y() + (double)eyeHeight, position.z());
        return distanceSq <= (double)maxDistanceSq;
    }

    public static boolean canPlayerInteractWithBlock(@Nonnull Ref<EntityStore> ref, @Nonnull ComponentAccessor<EntityStore> componentAccessor, @Nullable ItemStack heldItem, int blockX, int blockY, int blockZ) {
        double dz;
        double dy;
        Player playerComponent = componentAccessor.getComponent(ref, Player.getComponentType());
        if (playerComponent == null) {
            return true;
        }
        TransformComponent transformComponent = componentAccessor.getComponent(ref, TransformComponent.getComponentType());
        if (transformComponent == null) {
            return false;
        }
        float maxDistanceSq = InteractionValidation.getPlayerInteractionDistanceSq(ref, componentAccessor, heldItem);
        float eyeHeight = InteractionValidation.getEyeHeight(ref, componentAccessor);
        Vector3d position = transformComponent.getPosition();
        double dx = (double)blockX + 0.5 - position.x();
        double distanceSq = dx * dx + (dy = (double)blockY + 0.5 - (position.y() + (double)eyeHeight)) * dy + (dz = (double)blockZ + 0.5 - position.z()) * dz;
        return distanceSq <= (double)maxDistanceSq;
    }

    public static boolean canPlayerInteractWithBlock(@Nonnull Ref<EntityStore> ref, @Nonnull ComponentAccessor<EntityStore> componentAccessor, @Nullable ItemStack heldItem, @Nonnull Vector3i blockPosition) {
        return InteractionValidation.canPlayerInteractWithBlock(ref, componentAccessor, heldItem, blockPosition.x, blockPosition.y, blockPosition.z);
    }

    public static boolean canPlayerInteractWithBlock(@Nonnull Ref<EntityStore> ref, @Nonnull ComponentAccessor<EntityStore> componentAccessor, @Nullable ItemStack heldItem, @Nonnull BlockPosition blockPosition) {
        return InteractionValidation.canPlayerInteractWithBlock(ref, componentAccessor, heldItem, blockPosition.x, blockPosition.y, blockPosition.z);
    }
}

