        @Nonnull
        private final ComponentType<EntityStore, EntityViewer> entityViewerComponentType;
        @Nonnull
        private final ComponentType<EntityStore, BoundingBox> boundingBoxComponentType;
        @Nonnull
        private final Query<EntityStore> query;
        @Nonnull
        private final Set<Dependency<EntityStore>> dependencies;

        public LODCull(@Nonnull ComponentType<EntityStore, EntityViewer> entityViewerComponentType) {
            this.entityViewerComponentType = entityViewerComponentType;
            this.boundingBoxComponentType = BoundingBox.getComponentType();
            this.query = Query.and(entityViewerComponentType, TransformComponent.getComponentType());
            this.dependencies = Collections.singleton(new SystemDependency(Order.AFTER, CollectVisible.class));
        }

