    @Override
    protected void start() {
        DamageCause.PHYSICAL = (DamageCause)DamageCause.getAssetMap().getAsset("Physical");
        DamageCause.PROJECTILE = (DamageCause)DamageCause.getAssetMap().getAsset("Projectile");
        DamageCause.COMMAND = (DamageCause)DamageCause.getAssetMap().getAsset("Command");
        DamageCause.DROWNING = (DamageCause)DamageCause.getAssetMap().getAsset("Drowning");
        DamageCause.ENVIRONMENT = (DamageCause)DamageCause.getAssetMap().getAsset("Environment");
        DamageCause.FALL = (DamageCause)DamageCause.getAssetMap().getAsset("Fall");
        DamageCause.OUT_OF_WORLD = (DamageCause)DamageCause.getAssetMap().getAsset("OutOfWorld");
        DamageCause.SUFFOCATION = (DamageCause)DamageCause.getAssetMap().getAsset("Suffocation");
        if (DamageCause.PHYSICAL == null || DamageCause.PROJECTILE == null || DamageCause.COMMAND == null || DamageCause.DROWNING == null || DamageCause.ENVIRONMENT == null || DamageCause.FALL == null || DamageCause.OUT_OF_WORLD == null || DamageCause.SUFFOCATION == null) {
            throw new IllegalStateException("Missing default DamageCause assets");
        }
    }

