    @Deprecated
    @Nullable
    public <T extends Entity> T addEntity(T entity, @Nonnull Vector3d position, @Nullable Rotation3f rotation, @Nonnull AddReason reason) {
        if (!EntityModule.get().isKnown(entity)) {
            throw new IllegalArgumentException("Unknown entity");
        }
        if (entity instanceof Player) {
            throw new IllegalArgumentException("Entity can't be a Player!");
        }
        if (entity.getNetworkId() == -1) {
            throw new IllegalArgumentException("Entity id can't be Entity.UNASSIGNED_ID (-1)!");
        }
        if (!this.equals(entity.getWorld())) {
            throw new IllegalStateException("Expected entity to already have its world set to " + this.getName() + " but it has " + String.valueOf(entity.getWorld()));
        }
        if (entity.getReference() != null && entity.getReference().isValid()) {
            throw new IllegalArgumentException("Entity already has a valid EntityReference: " + String.valueOf(entity.getReference()));
        }
        if (position.y() < -32.0) {
            throw new IllegalArgumentException("Unable to spawn entity below the world! -32 < " + String.valueOf(position));
        }
        if (!this.isInThread()) {
            ((HytaleLogger.Api)this.logger.at(Level.WARNING).withCause(new SkipSentryException())).log("Warning addEntity was called off thread!");
            this.execute(() -> this.addEntity(entity, position, rotation, reason));
            return entity;
        }
        entity.unloadFromWorld();
        Holder<EntityStore> holder = entity.toHolder();
        HeadRotation headRotation = holder.ensureAndGetComponent(HeadRotation.getComponentType());
        if (rotation != null) {
            headRotation.teleportRotation(rotation);
        }
        holder.addComponent(TransformComponent.getComponentType(), new TransformComponent(position, rotation));
        holder.ensureComponent(UUIDComponent.getComponentType());
        this.entityStore.getStore().addEntity(holder, reason);
        return entity;
    }

    @Override
    public void sendMessage(@Nonnull Message message) {
        if (!this.isInThread()) {
            this.execute(() -> this.sendMessage(message));
            return;
        }
        this.entityStore.getStore().forEachEntityParallel(PlayerRef.getComponentType(), (index, archetypeChunk, commandBuffer) -> {
            PlayerRef playerRefComponent = archetypeChunk.getComponent(index, PlayerRef.getComponentType());
            assert (playerRefComponent != null);
            playerRefComponent.sendMessage(message);
        });
        this.logger.at(Level.INFO).log("[Broadcast] [Message] %s", MessageUtil.toAnsiString(message).toAnsi(ConsoleModule.get().getTerminal()));
    }

    @Override
    public void execute(@Nonnull Runnable command) {
        if (!this.acceptingTasks.get()) {
            throw new SkipSentryException(new IllegalThreadStateException("World thread is not accepting tasks: " + this.name + ", " + String.valueOf(this.getThread())));
        }
        this.taskQueue.offer(command);
    }

    @Override
    public void consumeTaskQueue() {
        Runnable runnable;
        this.debugAssertInTickingThread();
        int tickStepNanos = this.getTickStepNanos();
        while ((runnable = this.taskQueue.poll()) != null) {
            try {
                long before = System.nanoTime();
                runnable.run();
                long after = System.nanoTime();
                long diff = after - before;
                if (diff <= (long)tickStepNanos) continue;
                this.logger.at(Level.WARNING).log("Task took %s ns: %s", (Object)FormatUtil.nanosToString(diff), (Object)runnable);
            }
            catch (Exception t) {
                ((HytaleLogger.Api)this.logger.at(Level.SEVERE).withCause(t)).log("Failed to run task!");
            }
        }
    }

