    @Nullable
    public CompletableFuture<PlayerRef> addPlayer(@Nonnull PlayerRef playerRef, @Deprecated(forRemoval=true) @Nullable Transform transform, @Nullable Boolean clearWorldOverride, @Nullable Boolean fadeInOutOverride) {
        boolean fadeInOut;
        if (!this.alive.get()) {
            return CompletableFuture.failedFuture(new IllegalStateException("This world has already been shutdown!"));
        }
        if (playerRef.getReference() != null) {
            throw new IllegalStateException("Player is already in a world");
        }
        PacketHandler packetHandler = playerRef.getPacketHandler();
        if (!packetHandler.stillActive()) {
            return null;
        }
        Holder<EntityStore> holder = playerRef.getHolder();
        assert (holder != null);
        TransformComponent transformComponent = holder.getComponent(TransformComponent.getComponentType());
        if (transformComponent == null && transform == null && (transformComponent = SpawnUtil.applyFirstSpawnTransform(holder, this, this.worldConfig, playerRef.getUuid())) == null) {
            return CompletableFuture.failedFuture(new IllegalStateException("Spawn provider cannot be null for positioning new entities!"));
        }
        assert (transformComponent != null);
        Player playerComponent = holder.getComponent(Player.getComponentType());
        assert (playerComponent != null);
        boolean firstSpawn = !playerComponent.getPlayerConfigData().getPerWorldData().containsKey(this.name);
        playerComponent.setFirstSpawn(firstSpawn);
        if (transform != null) {
            SpawnUtil.applyTransform(holder, transform);
        }
        Message joinMessage = Message.translation("server.general.playerJoinedWorld").param("username", playerRef.getUsername()).param("world", this.worldConfig.getDisplayName() != null ? this.worldConfig.getDisplayName() : WorldConfig.formatDisplayName(this.name));
        AddPlayerToWorldEvent event = HytaleServer.get().getEventBus().dispatchFor(AddPlayerToWorldEvent.class, this.name).dispatch(new AddPlayerToWorldEvent(holder, this, joinMessage));
        ChunkTracker chunkTrackerComponent = holder.getComponent(ChunkTracker.getComponentType());
        boolean clearWorld = clearWorldOverride != null ? clearWorldOverride : true;
        boolean bl = fadeInOut = fadeInOutOverride != null ? fadeInOutOverride : true;
        if (chunkTrackerComponent != null && (clearWorld || fadeInOut)) {
            chunkTrackerComponent.setReadyForChunks(false);
        }
        Vector3d spawnPosition = transformComponent.getPosition();
        long chunkIndex = ChunkUtil.indexChunkFromBlock(spawnPosition.x(), spawnPosition.z());
        CompletionStage loadTargetChunkFuture = this.chunkStore.getChunkReferenceAsync(chunkIndex).thenAccept(v -> playerComponent.startClientReadyTimeout());
        CompletableFuture<Void> clientReadyFuture = new CompletableFuture<Void>();
        packetHandler.setClientReadyForChunksFuture(clientReadyFuture);
        CompletableFuture<Void> setupPlayerFuture = CompletableFuture.runAsync(() -> this.onSetupPlayerJoining(holder, playerComponent, playerRef, packetHandler, transform, clearWorld, fadeInOut));
        CompletableFuture<Void> playerReadyFuture = clientReadyFuture.orTimeout(30L, TimeUnit.SECONDS);
        return ((CompletableFuture)CompletableFuture.allOf(new CompletableFuture[]{setupPlayerFuture, playerReadyFuture, loadTargetChunkFuture}).thenApplyAsync(aVoid -> this.onFinishPlayerJoining(playerComponent, playerRef, packetHandler, event.getJoinMessage(), event.shouldBroadcastJoinMessage()), (Executor)this)).exceptionally(throwable -> {
            ((HytaleLogger.Api)this.logger.at(Level.WARNING).withCause((Throwable)throwable)).log("Exception when adding player to world!");
            PluginIdentifier possibleCause = PluginIdentifier.identifyThirdPartyPlugin(throwable);
            if (possibleCause == null) {
                playerRef.getPacketHandler().disconnect(Message.translation("server.general.disconnect.exceptionJoiningWorld"));
            } else {
                playerRef.getPacketHandler().disconnect(Message.translation("server.general.disconnect.exceptionJoiningWorldCause").param("cause", possibleCause.toString()));
            }
            throw new RuntimeException("Exception when adding player '" + playerRef.getUsername() + "' to world '" + this.name + "'", (Throwable)throwable);
        });
    }

    @Nonnull
    private PlayerRef onFinishPlayerJoining(@Nonnull Player playerComponent, @Nonnull PlayerRef playerRefComponent, @Nonnull PacketHandler packetHandler, @Nullable Message joinMessage, boolean shouldBroadcastJoinMessage) {
        Ref<EntityStore> ref;
        TimeResource timeResource = this.entityStore.getStore().getResource(TimeResource.getResourceType());
        float timeDilationModifier = timeResource.getTimeDilationModifier();
        int maxViewRadius = HytaleServer.get().getConfig().getMaxViewRadius();
        packetHandler.write(new ViewRadius(maxViewRadius * 32), new SetEntitySeed(this.entitySeed.get()), new SetClientId(playerComponent.getNetworkId()), new SetTimeDilation(timeDilationModifier));
        packetHandler.write((ToClientPacket)new UpdateFeatures(this.features));
        packetHandler.write((ToClientPacket)this.worldConfig.getClientEffects().createSunSettingsPacket());
        packetHandler.write((ToClientPacket)this.worldConfig.getClientEffects().createPostFxSettingsPacket());
        UUID playerUuid = playerRefComponent.getUuid();
        Store<EntityStore> store = this.entityStore.getStore();
        WorldTimeResource worldTimeResource = store.getResource(WorldTimeResource.getResourceType());
        World world = store.getExternalData().getWorld();
        packetHandler.writeNoCache(new SetUpdateRate(this.getTps()));
        if (this.isPaused) {
            this.setPaused(false);
        }
        if ((ref = playerRefComponent.addToStore(store)) == null || !ref.isValid()) {
            throw new IllegalStateException("Failed to add player ref of joining player to the world store");
        }
        worldTimeResource.sendTimePackets(playerRefComponent);
        WorldMapTracker worldMapTracker = playerComponent.getWorldMapTracker();
        worldMapTracker.clear();
        worldMapTracker.sendSettings(world);
        if (shouldBroadcastJoinMessage) {
            PlayerUtil.broadcastMessageToPlayers(playerUuid, joinMessage, store);
        }
        TransformComponent transformComponent = store.getComponent(ref, TransformComponent.getComponentType());
        assert (transformComponent != null);
        String position = transformComponent.getPosition().toString();
        this.logger.at(Level.INFO).log("Player '%s' joined world '%s' at location %s (%s)", playerRefComponent.getUsername(), this.name, position, playerUuid);
        HeadRotation headRotationComponent = store.getComponent(ref, HeadRotation.getComponentType());
        assert (headRotationComponent != null);
        return playerRefComponent;
    }

    private void onSetupPlayerJoining(@Nonnull Holder<EntityStore> holder, @Nonnull Player playerComponent, @Nonnull PlayerRef playerRefComponent, @Nonnull PacketHandler packetHandler, @Nullable Transform transform, boolean clearWorld, boolean fadeInOut) {
        UUID playerUuid = playerRefComponent.getUuid();
        this.logger.at(Level.INFO).log("Adding player '%s' to world '%s' at location %s (%s)", playerRefComponent.getUsername(), this.name, transform, playerUuid);
        int entityId = this.entityStore.takeNextNetworkId();
        playerComponent.setNetworkId(entityId);
        PlayerConfigData configData = playerComponent.getPlayerConfigData();
        configData.setWorld(this.name);
        if (clearWorld) {
            EntityTrackerSystems.clear(holder);
            ChunkTracker chunkTrackerComponent = holder.getComponent(ChunkTracker.getComponentType());
            if (chunkTrackerComponent != null) {
                chunkTrackerComponent.unloadAll(playerRefComponent);
            }
        }
        playerComponent.getPageManager().clearCustomPageAcknowledgements();
        JoinWorld packet = new JoinWorld(clearWorld, fadeInOut, this.worldConfig.getUuid());
        packetHandler.write((ToClientPacket)packet);
        packetHandler.tryFlush();
        HytaleLogger.getLogger().at(Level.INFO).log("%s: Sent %s", (Object)packetHandler.getIdentifier(), (Object)packet);
        packetHandler.setQueuePackets(true);
    }

    @Nonnull
    public CompletableFuture<Void> drainPlayersTo(@Nonnull World fallbackTargetWorld, Collection<PlayerRef> players) {
        ObjectArrayList<CompletableFuture<PlayerRef>> futures = new ObjectArrayList<CompletableFuture<PlayerRef>>();
        for (PlayerRef playerRef : players) {
            Holder<EntityStore> holder = playerRef.getReference() != null ? playerRef.removeFromStore() : playerRef.getHolder();
            DrainPlayerFromWorldEvent event = HytaleServer.get().getEventBus().dispatchFor(DrainPlayerFromWorldEvent.class, this.name).dispatch(new DrainPlayerFromWorldEvent(holder, fallbackTargetWorld, null));
            futures.add(event.getWorld().addPlayer(playerRef, event.getTransform()));
        }
        return CompletableFuture.allOf((CompletableFuture[])futures.toArray(CompletableFuture[]::new));
    }

